using System.Windows;using System.Windows.Controls;using FFPerformanceEngine.Core.Models;namespace FFPerformanceEngine.App.Pages;public partial class GuardianPage:UserControl{public GuardianPage(){InitializeComponent();Loaded+=(_,_)=>{App.Services.Guardian.SetState(GameState.Lobby);ModeText.Text=App.Services.Guardian.Mode.ToString();};}private void ModeCombo_Changed(object s,SelectionChangedEventArgs e){if(!IsLoaded||ModeCombo.SelectedItem is not ComboBoxItem item||item.Content is not string raw||!Enum.TryParse<GuardianMode>(raw,out var mode))return;App.Services.Guardian.Mode=mode;ModeText.Text=mode.ToString();}private void Evaluate_Click(object s,RoutedEventArgs e){App.Services.Guardian.SetState(GameState.Match);var action=new GuardianAction{Id="priority",Description="Ajuste de prioridade previamente validado",Safety=ActionSafety.LiveSafe,MinimumConfidence=.75};var d=App.Services.Guardian.Evaluate(120,new TelemetrySample{Fps=95,FrameTimeMs=10.5},action);StateText.Text=d.ShouldAct?"◉ Intervenção elegível":"● Observando";DecisionText.Text=$"{d.Reason} Confiança: {d.Confidence:P0}. Nenhuma mudança é executada nesta demonstração sem uma medição canary real.";}}